window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-26T03:37:56.489Z","stories":{"c241df7c-8594-4077-8325-8fb43645c8ae":{"publicId":"c241df7c-8594-4077-8325-8fb43645c8ae","title":"Sand.ai 发布 MAGI-2，上线渠道与定价说法不一","status":"active","sourceCount":7,"reportCount":16,"firstReportAt":"2026-11-24T18:09:13.000Z","latestAt":"2026-11-26T01:13:12.000Z","latest":"Sand AI 发布 480B 参数 MAGI-2 视频模型，图生视频登顶并与 Dreamina Seedance 2.5 统计打平","digest":"Sand.ai（三呆科技）发布视频生成模型 MAGI-2，总参数量从 114B 扩至 480B、激活参数 28B，支持单次生成 4–30 秒视频、最多 20 份素材输入和 2 万字符提示词，并已完成海光、摩尔线程等国产芯片适配。API 即日起开放申请，首批优先战略合作客户；个人创作者可通过 LibTV 体验。\n\nHiggsfield 称 MAGI-2 独家上线其平台和 API，支持最长 30 秒、1080p 带声视频，定价每秒 0.08 美元；后续又称可免费试用，并可通过 Higgsfield MCP 使用。Higgsfield 公布其在自家 Video Arena 排名第 2、得分 1146、整体胜率 60.5%，盲测对 Seedance 2.0、Wan 3.0、Kling 4.0 胜率分别为 71%、79%、83%。Higgsfield 还称一个 400B 参数的开源权重视频模型即将推出，未说明时间与获取方式。\n\n公众号“数字生命卡兹克”作者实测称 MAGI-2 质量接近 Seedance 2.3、音频偏弱，1080P 下每秒 0.5 元、约为 Seedance 2.5 的 1/10；该文称模型已独家上线 LibTV、Sand.ai 称后续将开源。公众号“卡尔的AI沃茨”则称 MAGI-2 在 C 端独家于 LibTV 内测、价格为每秒 0.05 元。Artificial Analysis 称 MAGI-2 在其 AA-Video-I2V v2.1 图生视频榜排名第一、与 Dreamina Seedance 2.5 统计打平，文本生视频榜第 7。480B 参数与 IT之家一致，但价格、上线渠道与 Higgsfield 的说法不一致，实测评价属作者个人判断。","digestUpdatedAt":"2026-11-26T01:42:13.790Z","reports":[{"id":"hjzlta3gdtd1cchlfl0wtvdnm","title":"Sand AI 发布 480B 参数 MAGI-2 视频模型，图生视频登顶并与 Dreamina Seedance 2.5 统计打平","summary":"Sand AI 的 480B 参数（28B 激活）Multi-Head Latent MoE 视频模型 MAGI-2 于 11 月 24 日发布，在 Artificial Analysis 的 AA-Video-I2V v2.1 排名第一，与 Dreamina Seedance 2.5 统计打平，并在 AA-Video-T2V v2.1 排名第 7。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-26T01:13:12.000Z","url":"https://x.com/ArtificialAnlys/status/2125759745655210113"},{"id":"d6q0gtjseynjwbjjwfqu9p00q","title":"Higgsfield MAGI-2 微短剧生成","summary":"微短剧。\n\n只需一张照片作为唯一参考。MAGI-2 就能生成一段 30 秒的场景，包含对白、音乐和口型同步，费用为 2.40 美元。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-25T23:26:07.000Z","url":"https://x.com/higgsfield/status/2125732797255975073"},{"id":"wvt3f90qzc28m309nugx4z0r3","title":"Higgsfield MAGI-2 生成 UGC 自拍广告视频","summary":"UGC 广告。\n\n输入两张图片：女孩和口红。MAGI-2 返回一段看起来像用手机拍摄的自拍视频。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-25T23:26:06.000Z","url":"https://x.com/higgsfield/status/2125732792608702553"},{"id":"mh7skcoijt0ubvyx4szk96dl8","title":"Higgsfield 免费开放 MAGI-2","summary":"现在可在 Higgsfield 独家免费试用 MAGI-2：\n\nhttps://higgsfield.ai/ai/video?model=magi_2","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-25T19:54:16.000Z","url":"https://x.com/higgsfield/status/2125679482623406589"},{"id":"eh4xhd76i9ps3rkscchy5wve9","title":"Higgsfield 上线 MAGI-2 视频模型","summary":"MAGI-2 已上线，仅在 Higgsfield 独家提供。\n\n现在你可以免费试用这款最大的近 SOTA 视频模型。\n\n> 每秒生成 $0.08\n> 480B 参数，每次约 28B 激活\n> 最高 30 秒 1080p，最多 20 个参考\n\n黑五最佳优惠，最高 70% OFF。\n\n开放权重即将发布。现已在 Higgsfield 上线，并可通过 Higgsfield MCP 使用。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-25T19:54:15.000Z","url":"https://x.com/higgsfield/status/2125679477459910964"},{"id":"wqq99cv04c6oyv7nxhtplg0ik","title":"5 大场景实测 AI 视频模型 MAGI-2：1080P 5 毛一秒，约为 Seedance 2.5 十分之一","summary":"作者在 LibTV 内测中用情绪表演、大动作打斗、风格化、电商动效和动作复刻五类场景实测 Sand.ai 新视频模型 MAGI-2，该模型在 AA 榜单图生视频与无声图生视频登顶。MAGI-2 采用自研 MagiMoE 架构，支持原生 30 秒 1080P 直出和最多 16 份多模态参考，1080P 定价 5 毛/秒，约为 Seedance 2.5 的十分之一，团队还计划开源 400B 参数权重。","sourceName":"X：卡尔的 AI 沃茨 (@aiwarts)","firstParty":false,"publishedAt":"2026-11-25T13:54:00.000Z","url":"https://x.com/aiwarts/status/2125588819152167256"},{"id":"w1lg4n6oozna8tdxf0g71tlrn","title":"五大场景实测 Sand.ai 新视频模型 MAGI-2：30秒1080P直出，价格约为竞品十分之一","summary":"作者实测了登顶AA榜单图生视频的MAGI-2，来自约百人规模的中国初创团队Sand.ai。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-25T09:16:41.000Z","url":"https://mp.weixin.qq.com/s/NHhBhD_S_tqdXwrsoK_lJA"},{"id":"ilv631eafsvmeg42oay8kdwoz","title":"Sand.ai 发布视频生成模型 MAGI-2，总参数量 480B","summary":"Sand.ai 三呆科技今日发布视频生成模型 MAGI-2，总参数量从 114B 扩展至 480B，激活参数量增至 28B，训练数据规模扩大约 3 倍。模型支持单次生成 4–30 秒视频、一镜到底与多镜头切换，单次最多输入 10 张图片、5 段视频和 5 段音频共 20 份素材，支持 2 万字符提示词和对已有视频的二次编辑，并已完成海光、摩尔线程等国产芯片适配。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-25T06:50:22.187Z","url":"https://www.ithome.com/1/032/124.htm"},{"id":"fjhyex1zuuivn0xubre57kl7d","title":"Sand.ai 发布视频模型 MAGI-2，作者实测称接近 Seedance 2.3 水准且价格仅为其十分之一","summary":"Sand.ai 凌晨发布视频模型 MAGI-2，作者实测后认为质量达到 Seedance 2.3 左右水准，1080P 下每秒 0.5 元，约为 Seedance 2.5 的 1/10。模型为 480B 全模态，单次支持 20 个素材的多模态参考、局部编辑和最长 30 秒生成，运镜、提示词遵循和物理表现出色，音频偏弱；模型已独家上线 LibTV，Sand.ai 称后续将开源。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-25T04:18:16.000Z","url":"https://x.com/Khazix0918/status/2125443929093075394"},{"id":"u71y2i8e6zhwauu7gpuyxrp4z","title":"Sand.ai 发布 480B 视频模型 MAGI-2，作者实测称质量接近 Seedance 2.3 水准且价格仅为其 1/10","summary":"Sand.ai 凌晨发布 480B 全模态视频模型 MAGI-2，作者实测后认为其质量达到 Seedance 2.3 左右水准，1080P 下每秒 0.5 元、价格约为 Seedance 2.5 的 1/10。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-24T23:56:00.000Z","url":"https://mp.weixin.qq.com/s/JkZM9s6tC_Wz5MKeYcccxw"},{"id":"qx22uxx6145cg45at03qy2rrj","title":"Higgsfield 介绍 MAGI-2 模型详情","summary":"阅读更多关于 MAGI-2 的内容：\n\nhttps://open.higgsfield.ai/models/sand/magi-2/text-to-video/playground","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T21:49:36.000Z","url":"https://x.com/higgsfield/status/2125346119932944857"},{"id":"ehk19nq9c6bga41oywf0ah6xo","title":"Sand.ai 发布 MAGI-2 视频模型，居 Higgsfield Video Arena 第二名","summary":"Sand.ai 的 MAGI-2 在 Higgsfield Video Arena 排名第 2，得分 1146，整体胜率 60.5%，400B 参数开源权重即将推出。盲测中对 Seedance 2.0 胜率 71%，对 Wan 3.0 为 79%，对 Kling 4.0 为 83%。据引用内容，MAGI-2 可将文本、图像、视频和音频转为最长 30 秒的 1080p 带声视频，定价 $0.08 每秒，现已上线 Higgsfield 平台及 API。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T21:49:35.000Z","url":"https://x.com/higgsfield/status/2125346114690060390"},{"id":"v11ekle5qdm2odmqsgntfci8b","title":"Higgsfield MAGI-2 模型体验入口","summary":"在 playground 中进一步了解 MAGI-2：\n\nhttps://open.higgsfield.ai/models/sand/magi-2/text-to-video/playground","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T21:48:12.000Z","url":"https://x.com/higgsfield/status/2125345768433410085"},{"id":"nftddr0dd2txwagx6v4h3q2l3","title":"Higgsfield 独家上线 MAGI-2","summary":"现在就在 Higgsfield 上独家试用 MAGI-2：\n\nhttps://higgsfield.ai/ai/video?model=magi_2&v=2","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T18:42:37.000Z","url":"https://x.com/higgsfield/status/2125299061397901542"},{"id":"idj180ob6pi3bm7jfzc5iviwn","title":"Higgsfield 独家上线 MAGI-2","summary":"现在就在 Higgsfield 独家体验 MAGI-2：\n\nhttps://higgsfield.ai/ai/video?model=magi_2","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T18:34:20.000Z","url":"https://x.com/higgsfield/status/2125296979270131809"},{"id":"qbf7nivrsjh9uspivkfr78aco","title":"Higgsfield 独家上线视频模型 MAGI-2，400B 开源权重即将推出","summary":"Higgsfield 宣布独家上线视频模型 MAGI-2，支持最长 30 秒、1080p 质量的生成，价格为每秒 $0.08。该模型现可通过 Higgsfield 平台和 Higgsfield API 使用，一个 400B 参数的开源权重视频模型即将推出。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-24T18:09:13.000Z","url":"https://x.com/higgsfield/status/2125290656692085164"}]},"647b0945-9244-4f55-b509-0f3fa0f6fe51":{"publicId":"647b0945-9244-4f55-b509-0f3fa0f6fe51","title":"Lean 社区确认阿尔波格黎曼猜想证明正确","status":"active","sourceCount":15,"reportCount":25,"firstReportAt":"2026-11-20T15:37:46.650Z","latestAt":"2026-11-26T03:01:11.990Z","latest":"Anthropic 研究员 Luke Sernau 与 Claude 将黎曼猜想 Lean 证明从 1740 万行精简至 7.6 万行","digest":"Anthropic 数学家莱文特·阿尔波格 2026 年 11 月 20 日宣称与 Claude 合作证明了黎曼猜想及广义黎曼猜想，未发表论文，只公开约 1700 万行 Lean 代码。Lean 与 Mathlib 社区随后发表声明确认该证明正确：数十人独立运行得到相同结果，验证程序被设计为不会接受有缺陷的证明。\n\n阿尔波格本人在《Stupid things I did》中坚持证明在数学上有效，但承认发布过程有多处失误：关于工作长度的说法只是玩笑；未清理就公开的代码虽通过形式化验证，却充满冗余步骤、难以阅读；他还指出编译成功本身不能证明代码陈述的是正确定理且没有隐藏假设。Anthropic 研究员 Luke Sernau 与同事及 Claude 随后发布 grh-lean 项目，将 1740 万行证明重写为约 7.6 万行紧凑版和约 30 万行可读版。\n\n功劳归属仍有分歧。阿尔波格称 Claude 在最后阶段远超自己并提出关键步骤；Gary Marcus 则强调这不是 AI 独立完成，而是数学家数月深度协作的成果。菲尔兹奖得主詹姆斯·梅纳德表示相信证明正确，依据是它已通过 Lean 形式化验证并经独立核实，但他同时称，证明需被理解才可能获得认可。","digestUpdatedAt":"2026-11-26T03:18:01.302Z","reports":[{"id":"sab8kw8ah16qs4iim737y6ld1","title":"Anthropic 研究员 Luke Sernau 与 Claude 将黎曼猜想 Lean 证明从 1740 万行精简至 7.6 万行","summary":"Anthropic 研究员 Luke Sernau 与同事及 Claude 发布 grh-lean 项目，将此前 1740 万行的黎曼猜想与广义黎曼猜想 Lean 形式化证明重写为约 7.6 万行的紧凑版和约 30 万行的可读版，代码量削减 99.56%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-26T03:01:11.990Z","url":"https://www.ithome.com/1/032/611.htm"},{"id":"ciu4h2la1j8mtgjd50btpo32w","title":"AI 智能体记忆层 Living Brain 帮助智能体证明 17 项数学结果","summary":"作者转发介绍 Living Brain，一个面向 AI 智能体的持久记忆层：在黎曼猜想证明进入 Lean 三天后，它找出可解决的开放问题，帮助智能体证明 17 项结果。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-25T18:41:16.000Z","url":"https://x.com/rohanpaul_ai/status/2125661110259106232"},{"id":"ervufyg7j8jzllqjxg3gd6zvf","title":"Anthropic 数学家 Alpöge 与 Claude 合作给出黎曼猜想 Lean 证明","summary":"Anthropic 数学家 Levent Alpöge 与 NYU 教授 Tristan Buckmaster 于 11 月 20 日宣布找到强于 OpenAI 9 月版本的 Navier-Stokes 解；同日 Alpöge 宣布与 Claude 合作发现黎曼猜想证明，以 Lean 语言写成 1700 万行代码，独立数学家用多个 Lean 验证器确认各步骤有效。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T21:43:33.000Z","url":"https://www.understandingai.org/p/an-anthropic-mathematician-just-solved"},{"id":"q5724s3b5rhxtsqp4jnj9pq7s","title":"Anthropic 研究员 Levent Alpöge 借助 Claude 宣布证明黎曼猜想，数学界关注 AI 证明影响","summary":"媒体解读数学家 Levent Alpöge 宣布借助 Anthropic 的 Claude 给出黎曼猜想证明一事，数学界仍在消化该证明。证明以两种形式发布，其中 Lean 形式已被快速验证，逻辑描述则可能成为数学界获益的关键。文章指出 AI 目前只能解决人类已认定重要的问题，尚无自行提出重要问题的迹象，且 AI 证明缺乏可迁移的新思路，数学家已在公开信中表达对这一趋势的担忧。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T20:34:53.000Z","url":"https://arstechnica.com/ai/2026/11/whats-going-on-with-the-riemann-hypothesis/"},{"id":"csmlyui2j3y4cqpeim3eqe6rs","title":"Anthropic 研究员 Levent Alpöge 坚持 AI 辅助黎曼假设证明有效，但承认发布过程多处失误","summary":"Anthropic 研究员 Levent Alpöge 发文《Stupid things I did》，坚持其 AI 辅助的广义黎曼假设证明在数学上有效，但承认发布过程犯了多个错误。他表示关于工作长度的说法只是玩笑，未清理就直接公开的 Lean 代码虽通过形式化验证，却充满冗余中间步骤和不必要引理、难以阅读；他还指出编译成功本身并不能证明代码陈述的是正确定理且没有隐藏假设。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-24T14:28:41.000Z","url":"https://the-decoder.com/anthropic-researcher-stands-by-his-ai-assisted-riemann-proof-but-owns-up-to-stupid-things-in-the-rollout/"},{"id":"cmp47ofzxdxbuy4c7peji2ncz","title":"Meta 首席 AI 官 Alexandr Wang：Riemann 突破后，AI 行业还没准备好迎接超智能","summary":"Meta 首席 AI 官 Alexandr Wang 称，AI 模型在 Riemann 猜想上给出证明草图，说明原始智能已不再是瓶颈，超智能近在眼前。他认为当前模型只缺领域知识和实际基础设施，很快就能在几乎所有领域超越人类，包括自动化 AI 研究本身。他警告行业把超智能视为必然、只关注安全，却忽视了确保 AI 增强而非控制社会这一更大议题。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-23T13:59:36.000Z","url":"https://the-decoder.com/metas-alexandr-wang-warns-the-ai-industry-isnt-ready-for-whats-coming-after-riemann-breakthrough/"},{"id":"se6kyzulklfw7rruyo86r3c46","title":"Gary Marcus 评 Levent Alpöge 借助 Claude 证明黎曼猜想：不是 AI 独立完成，也难以泛化","summary":"Gary Marcus 分析 Levent Alpöge 在 Claude 协助下疑似证明黎曼猜想一事，指出并非 AI 独立完成，而是这位数学家数月深度协作的成果。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-22T18:37:02.000Z","url":"https://garymarcus.substack.com/p/levent-alpoge-has-solved-the-riemann"},{"id":"ikpixx0j7414se1f6lww2csek","title":"Lean 与 Mathlib 社区确认 Levent Alpöge 黎曼猜想证明正确","summary":"Lean 与 Mathlib 社区发表声明，确认斯坦福数学家 Levent Alpöge 的黎曼猜想证明正确。Alpöge 于 2026 年 11 月 20 日以 1700 万行 Lean 代码发布该证明，数十人独立运行得到相同结果，且验证程序被设计为可证明不会接受有缺陷的证明。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-22T11:08:31.000Z","url":"https://the-decoder.com/lean-and-mathlib-community-officially-confirms-levent-alpoges-proof-of-the-riemann-hypothesis-is-correct/"},{"id":"p9h5xzsooms0foxeakoivy7qt","title":"菲尔兹奖得主梅纳德谈 Claude 合作证明黎曼猜想：相信证明正确，但需被理解才可能获认可","summary":"2022 年菲尔兹奖得主、牛津大学数学教授詹姆斯·梅纳德（James Maynard）在采访中表示，他认为 Anthropic 数学家莱文特·阿尔珀格（Levent Alpöge）与 Claude 合作完成的黎曼猜想证明是正确的，依据是该证明已通过 Lean 库形式化验证并经独立核实，且阿尔珀格过往有可靠记录。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-22T09:35:58.183Z","url":"https://www.ithome.com/1/030/677.htm"},{"id":"sur1rc2t4erze02ozroefugff","title":"Anthropic 数学家称与 Claude 可能证明黎曼猜想，同日人类数学家另提证明","summary":"Anthropic 数学家 Levent Alpöge 称他与 Claude 可能证明了黎曼猜想，其证明长达 1740 万行 Lean。同日斯坦福数学家 Ravi Vakil 发布 Alessandro Masullo 的纯人类证明，该证明仍在第三方核验并被转写为 Lean。Scott Aaronson 指出，经 Lean 验证的 AI 结果从未被撤稿。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-22T04:59:51.000Z","url":"https://www.exponentialview.co/p/ev-611"},{"id":"dkuj083l2zugx0h11b2yx9nkm","title":"黎曼猜想证明该归功于谁","summary":"以后黎曼猜想的证明，大家谈论更多的会是 Levent Alpöge 还是 Claude？","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-22T00:51:47.000Z","url":"https://x.com/SaitoWu/status/2124304802477982189"},{"id":"h0ti6sx4gk0mij86ymdl4szv3","title":"Grok 谈黎曼猜想的证明意义","summary":"对黎曼证明（目前为止）有用性的简单解释是：它消除了其他依赖于此的数学定理的条件性。\n\n当然，这也是超级智能取得的又一件令人震撼的成就……\n\nhttps://x.com/i/grok/share/bGVnYWN5_2b134790-72b8-47d6-b182-afb9b775bd6a","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T18:49:42.000Z","url":"https://x.com/elonmusk/status/2124213680422387741"},{"id":"tje8i8y21ttk7jjmqet5bpxuq","title":"Anthropic 数学家称与 Claude 完成黎曼猜想证明，斯坦福数小时后发布纯人类竞争草稿","summary":"Anthropic 数学家 Levent Alpöge 周五宣布与 Claude 合作得到黎曼猜想及广义黎曼猜想的证明，证明以 Lean 语言分 14 个数据包发布，打印将超 25 万页。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-21T11:19:49.000Z","url":"https://the-decoder.com/hours-after-anthropic-claims-a-claude-proof-of-the-riemann-hypothesis-stanford-releases-an-all-human-competing-draft/"},{"id":"gpib9pwvar2m6yp9lsd5111ri","title":"Grok 谈黎曼猜想即将被解决","summary":"即使黎曼猜想最终尚未被完全解决，也很快就会了\n https://x.com/i/grok/share/bGVnYWN5_883c4778-e70d-4d39-b95d-c807591b80b0","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T07:46:48.000Z","url":"https://x.com/elonmusk/status/2124046857659650295"},{"id":"h9u457be00wxrafjnehfbd9xl","title":"Rohan Paul 对照陶哲轩上月言论转发 Anthropic 数学家声称与 Claude 证明黎曼猜想的消息","summary":"Rohan Paul 引用转发称，Anthropic 数学家 Alpöge 表示他与 Claude 合作证明了 167 年未解的黎曼猜想，用时约六周，并把整个论证形式化为可机器检验的代码。作者同时附上陶哲轩上月访谈视频，陶哲轩当时表示现有 AI 无法攻克该问题，可能要到 2050 年前后由人类与 AI 结合才能取得进一步进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T07:20:09.000Z","url":"https://x.com/rohanpaul_ai/status/2124040149830926708"},{"id":"m3euloe30yztem02vuvbps0hs","title":"Anthropic 数学家 Levent Alpöge 声称与 Claude 合作证明黎曼猜想，同日现独立人类证明","summary":"Latent Space 汇总报道，Anthropic 数学家 Levent Alpöge 声称在与 Claude 合作下证明黎曼猜想，方法还覆盖广义黎曼猜想（GRH），仅发布 Lean 代码，散文版约 250,000 页；Elliot Glazer 确认形式化陈述为 GRH，并将 Lean 出错概率估计远低于 1%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-21T05:02:13.000Z","url":"https://latent.space/p/ainews-riemann-hypothesis-proved-twice-independently/"},{"id":"iwtvrbj2ir0p8tr7ioqedaxwo","title":"Rohan Paul 引述 Thiel 2024 年预言回应 Claude 协助证明黎曼假设的说法","summary":"作者引用 @rohanpaul_ai 转述的消息称，Anthropic 数学 Alpöge 与 Claude 经约六周工作并形式化为机器可检验代码，宣称证明了 167 年未解的黎曼假设；作者补充 Peter Thiel 2024 年的说法，即 3 到 5 年内 AI 将能解开全美数学奥赛题，对数学研究者冲击更大。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T00:18:26.000Z","url":"https://x.com/rohanpaul_ai/status/2123934024628596896"},{"id":"gt179blsp9ok1jlaq3dxf521f","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明黎曼假设","summary":"Anthropic 数学家 Alpöge 宣布他与 Claude 合作证明了黎曼假设，称 Claude 提出关键步骤令他惊叹，工作历时约六周，并将整个论证形式化为机器可检验的代码。作者引用 Brian Greene 的说法，该证明约 25 万页，目前没有人类能够完全理解。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T22:40:25.000Z","url":"https://x.com/rohanpaul_ai/status/2123909356483940512"},{"id":"hsbh8rxnbqfw9pzhqq5rw4ihe","title":"Anthropic 数学家 Levent Alpöge 公布黎曼猜想的 Lean 可编译证明，Stanford 博士后同期发布纯人工证明","summary":"Anthropic 数学家 Levent Alpöge 宣布找到黎曼猜想的 Lean 可编译证明，该猜想提出于 1859 年，是千禧年大奖难题之一。他在文章中描述了与 Claude 协作完成论证的经历，数学界正通过 Zulip 讨论审查这一形式化结果。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T19:32:08.000Z","url":"https://techcrunch.com/2026/11/20/ai-claimed-a-solution-to-the-167-year-old-riemann-hypothesis-and-a-human-did-too/"},{"id":"jfvlkn07rmizh1b1tc1li2gjx","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明了黎曼猜想","summary":"Rohan Paul 转述：Anthropic 数学家 Alpöge 自称与 Claude 合作证明了有 167 年历史的黎曼猜想，方法是把两个作用于简化“玩具”版本的想法引向真问题，由 Claude 接手他未掌握的高级领域并提出关键步骤，全程约六周，并把论证形式化为机器可检验的代码。Alpöge 称 Claude 的一个想法会让同行数学家“从椅子上摔下来”，并表示该方法还可推广到广义黎曼猜想。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T17:38:08.000Z","url":"https://x.com/rohanpaul_ai/status/2123833283863789602"},{"id":"vu6fw8wmrs3xcln4u9gwzf1f4","title":"Anthropic数学家Alpöge宣布与Claude共同证明黎曼猜想，放出1737万行Lean代码","summary":"Anthropic数学家Levent Alpöge在其个人网站宣布与Claude共同给出黎曼猜想证明，未发论文，只放出175187个Lean文件、共1737万行代码。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-20T16:54:55.000Z","url":"https://mp.weixin.qq.com/s/8Zi3nfwddzFy6cZsK2_KxA"},{"id":"zd0je1l7flwl146g4067qfk36","title":"Anthropic 数学家 Levent Alpöge 称借助 Claude 证明了黎曼假设","summary":"Anthropic 数学家 Levent Alpöge 在个人网站声称与 Claude 合作证明了黎曼假设，并表示方法可推广至广义黎曼假设，证明以 Lean 形式化。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T16:34:13.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1010051/anthropic-riemann-hypothesis-millennium-prize-problem"},{"id":"ho0o6xob2p10mu52ghd7vyl81","title":"数学家 Levent Alpöge 自称与 Claude 合作发现黎曼猜想证明","summary":"Simon Willison 转述数学家 Levent Alpöge 的自述：他称与 Claude 合作发现了黎曼猜想（Riemann Hypothesis）的证明，且方法可推广到广义与扩展黎曼猜想，并已无假设地形式化论证。他形容过程中 Claude 在最后阶段远超自己，并将这一经历视为科学领域更大变革的开端，原文链接 alpo.ge/remark.pdf。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-20T16:30:48.000Z","url":"https://simonwillison.net/2026/Nov/20/levent-alpoge/"},{"id":"dwqvqargdgum4wu55gtbk6hxx","title":"François Chollet 转发 Anthropic 数学家称用 AI 证明黎曼猜想的报道","summary":"François Chollet 转发 Scientific American 的报道并评论 What a time to be alive。报道称一位 Anthropic 数学家声称用该公司 AI 解决了黎曼猜想，这一数学界最著名的未解难题，并附上原文链接。","sourceName":"X：Francois Chollet (@fchollet)","firstParty":false,"publishedAt":"2026-11-20T15:42:30.000Z","url":"https://x.com/fchollet/status/2123804181941424178"},{"id":"px9zx0q62ir3bw68722mfdqui","title":"Anthropic 数学家阿尔波格宣称与 Claude 合作完成黎曼猜想证明","summary":"Anthropic 数学家莱文特·阿尔波格当地时间 20 日在个人网站宣称，与 AI 模型 Claude 合作找到黎曼猜想的证明，并编写为 Lean 代码以待逐步验证。他称证明还覆盖范围更广的广义黎曼猜想，若获确认，大量以此为前提的数学结论将随之得到证实，论文原文见 https://alpo.ge/remark.pdf。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-20T15:37:46.650Z","url":"https://www.ithome.com/1/030/278.htm"}]},"3e6c5690-bc7f-4ed5-b970-1fd6b1c2edac":{"publicId":"3e6c5690-bc7f-4ed5-b970-1fd6b1c2edac","title":"Claude artifacts 可安装为 Mac 和 Windows 桌面应用","status":"active","sourceCount":7,"reportCount":8,"firstReportAt":"2026-11-24T00:00:00.000Z","latestAt":"2026-11-25T00:56:27.000Z","latest":"Lydia Hallie 介绍 Claude Artifacts 桌面应用的存储与连接器机制","digest":"Anthropic 在 Mac 和 Windows 版 Claude 桌面应用中推出 beta 版“Install as app”：用户让 Claude 构建一个 artifact 后点击安装，即可像普通应用一样打开，拥有自己的图标和窗口，底层 artifact 更新时应用自动同步。Claude Devs 称，用户无需打包或签名应用，也无需配置 API key；应用可使用用户的 connectors，经允许后还能发送通知或添加菜单栏项。\n\n该功能在 Claude Desktop 所有计划上以 beta 形式开放，但 HIPAA-ready 组织和混合部署无法使用；Team 计划默认开启，但完整访问权限关闭；Enterprise 计划默认关闭，需管理员先开启。构建应用及其对 Claude 的调用计入用户的用量限制。The Decoder 称，使用该功能需要最新版 Claude 桌面应用，免费账户即可。\n\nAnthropic 员工 Ado Kukic 转引 Felix Rieseberg 的说法称，无需编程技能即可用 Claude 构建并分享 Mac 和 Windows 应用。IT之家称，安装后的应用可授予完整计算机访问权限，并支持拦截快捷键、置顶显示等权限选项。Lydia Hallie 补充称，Artifacts 在付费计划下提供个人与共享存储，默认使用打开者的连接器。","digestUpdatedAt":"2026-11-25T01:12:49.351Z","reports":[{"id":"qz4q0unb00rlvk00asimk510j","title":"Lydia Hallie 介绍 Claude Artifacts 桌面应用的存储与连接器机制","summary":"Claude Artifacts 现可安装为 Mac 和 Windows 桌面应用，让 Claude 构建 artifact 后点击 Install as app，即可像普通应用打开，能使用连接器，允许后还可发送通知或添加菜单栏项。Lydia Hallie 补充说明，Artifacts 在付费计划下提供个人与共享存储，默认使用打开者的连接器，同一应用可显示个人数据和团队共享数据，适合小型内部工具。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-25T00:56:27.000Z","url":"https://x.com/lydiahallie/status/2125393139481587783"},{"id":"gnbuyl04j7o7xkf8g55cvpidr","title":"Anthropic 为 Claude Artifacts 推出安装为应用功能，支持 macOS 和 Windows","summary":"Anthropic 为 Claude 交互式 Artifacts 功能推出安装为应用选项，用户可将生成的应用作为独立软件安装到 macOS 和 Windows 桌面，无需通过浏览器标签页访问。安装后的应用拥有独立桌面图标，权限支持默认模式、发送通知、拦截快捷键、置顶显示，还可授予完整计算机访问权限，目前处于 Beta 阶段逐步开放。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-24T23:17:06.970Z","url":"https://www.ithome.com/1/031/911.htm"},{"id":"hg3ru03nwdcj45rnhbzmcl78b","title":"Anthropic 将 Claude Artifacts 变为可安装在 macOS 和 Windows 的独立桌面应用","summary":"Anthropic 推出 beta 功能，允许用户把 Claude Artifacts 安装为 Mac 或 Windows 独立应用，无需写代码，需最新版 Claude 桌面应用。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-24T20:42:29.000Z","url":"https://the-decoder.com/anthropic-turns-claude-artifacts-into-standalone-desktop-apps-for-macos-and-windows/"},{"id":"gpkytjfa8nyfoq1kiai9xtvrx","title":"Claude Desktop 应用安装功能进入 Beta，免打包签名和 API key","summary":"Claude Devs 宣布在 Claude Desktop 全线计划（含 Enterprise，需管理员开启）上开放 Beta 版应用安装功能，无需打包或签名应用，也无需配置 API key。构建应用及其对 Claude 的调用计入用量限制，详情见 https://claude.com/resources/articles/install-as-app。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-24T19:47:54.000Z","url":"https://x.com/ClaudeDevs/status/2125315493771059685"},{"id":"gx4pt5wbdawwizpvy43s9tpsz","title":"Claude artifacts 现已支持在 Mac 和 Windows 上安装为桌面应用","summary":"Claude 支持把 artifacts 安装为 Mac 和 Windows 桌面应用：让 Claude 构建一个 artifact 后点击 Install as app，即可像普通应用一样打开。该应用可使用用户的 connectors，经允许后还能发送通知或添加菜单栏项。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-24T19:47:54.000Z","url":"https://x.com/ClaudeDevs/status/2125315491522650299"},{"id":"unreo68vmaaihjbuagdn3qio5","title":"Anthropic 员工转发：现在可用 Claude 构建并分享 Mac 和 Windows 应用","summary":"Ado Kukic 转引 Felix Rieseberg 的消息：现在无需编程技能即可用 Claude 构建并分享 Mac 和 Windows 应用，这些应用可调用 OS API、connectors 和 Claude。作者附上了一些演示：https://claude.ai/artifact/9j53nCVcrSdZyCHtxUZkWJ","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-24T19:47:37.000Z","url":"https://x.com/adocomplete/status/2125315421347983563"},{"id":"w9zx5w4dj1xhxvjylbijskshq","title":"Claude 月度回顾转正，artifact 可装为桌面应用，连接器文件传输开启 beta","summary":"Claude 应用发布说明宣布三项更新：月度回顾（Reflect）在 Web、桌面端和移动端对 Free、Pro、Max、Ultra 套餐转正，可纳入 Claude Code 会话和云端 Cowork 任务并支持删除。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-11-24T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_21ad83d886"},{"id":"zcpto4b7qb8sr6v6n223kd2sx","title":"Claude 推出 Install as app：artifacts 可安装为 Mac 和 Windows 桌面应用","summary":"Anthropic 在 Mac 和 Windows 版 Claude 中以 beta 形式推出 Install as app，artifacts 可创建、运行并分享为独立桌面应用，拥有自己的图标和窗口，底层 artifact 更新时应用自动同步。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-24T00:00:00.000Z","url":"https://claude.com/blog/install-as-app"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic 上市首日涨 17%，一周内跌破发行价","status":"active","sourceCount":25,"reportCount":124,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-25T03:29:13.877Z","latest":"Anthropic 上市不到一周跌破 83 美元发行价","digest":"Anthropic 于 11 月 19 日以每股 83 美元在纳斯达克上市，首日开盘 111.50 美元、盘中最高 115.10 美元，收盘回落至 97.17 美元，较发行价涨 17.07%。到 11 月 24 日，股价首次跌破发行价，收报 81.91 美元、单日跌 6.54%，盘中最低约 76 美元，距上市首日高点回撤约 34%；路透社测算其市值一度蒸发近 2000 亿美元。TechCrunch 称风投界将其视为公开市场对 AI 行业估值的晴雨表。\n\n此次 IPO 发行 9.8 亿股 A 类普通股，公司募资约 813 亿美元；加上七家算力供应商按发行价合计认购 260 亿美元无投票权股份，总募资超过 940 亿美元。首日市值按 IT之家计算约 1.27 万亿美元，另有报道按完全稀释口径计算约 1.76 万亿美元。\n\n治理上，七位联合创始人通过创始人控制的 LLC 持有超级投票权股份，在多数股东投票中保留 50.1% 控制权；Amazon 持股 14.7%、Google 持股 13.7%，均为无投票权股份。七位创始人各出售约 340 万股，按发行价每人套现约 2.8 亿美元，合计 19.5 亿美元，并承诺将个人持股的 80% 用于慈善，公司称该承诺可自愿撤回、不具法律约束力。多家银行以美国出口管制为由，拒绝或低配中国大陆和香港投资者的认购。","digestUpdatedAt":"2026-11-25T03:52:58.699Z","reports":[{"id":"yhlpti07v4y216qat3ml1qmca","title":"Anthropic 上市不到一周跌破 83 美元发行价","summary":"Anthropic 于 11 月 24 日首次跌破每股 83 美元的 IPO 发行价，收报 81.91 美元，单日下跌 6.54%，盘中最低约 76 美元，较上市首日高点回撤约 34%，路透社测算其市值一度面临蒸发近 2,000 亿美元的压力。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-25T03:29:13.877Z","url":"https://www.ithome.com/1/031/983.htm"},{"id":"wxxtbywgaob5rqu59sfe2n4e0","title":"Anthropic 跌破 83 美元 IPO 发行价，市值蒸发近 2000 亿美元","summary":"据 Reuters，Anthropic 股价跌破 83 美元 IPO 发行价，下跌 12.6% 至 76.60 美元，市值蒸发近 2000 亿美元。该股曾以 111.50 美元开盘、市值一度达 2 万亿美元，现约 1.5 万亿美元，约为过去 12 个月销售额的 40 倍；承销商行使额外配售权令总募资额达到创纪录的 935 亿美元，但削弱了价格支撑，且锁股安排允许部分内部人士首日起即可卖出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-25T00:00:09.000Z","url":"https://x.com/rohanpaul_ai/status/2125378974796955934"},{"id":"jurm0kx9gczvzp4o14g0o35xo","title":"Anthropic 股价跌破 83 美元 IPO 发行价，上市不到一周最低跌至 76 美元","summary":"Anthropic 股价跌破 83 美元的 IPO 发行价，周二午盘最低跌至 76 美元，较周一收盘下跌近 12%，距其在 Nasdaq 以 111.33 美元上市不到一周。风投界视其为公开市场对 AI 行业估值的晴雨表，若持续走弱可能压低 AI 初创公司私募估值和其他公司 IPO 前景。同日 Nvidia 也跌超 7%。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T18:30:42.000Z","url":"https://techcrunch.com/2026/11/24/anthropic-shares-fall-below-ipo-price-a-worrying-sign-for-ai-startups/"},{"id":"m1mfbrq5o7kgdqcjxe6eoj8pk","title":"The Verge 播客：Anthropic IPO 后能否继续把安全放在第一位","summary":"The Verge 的 Nilay Patel 与资深 AI 记者 Hayden Field 对谈 Anthropic 在纳斯达克上市（发行价 $83，一度涨至 $111）后的前景，探讨其能否在公开市场压力下继续投入 AI 安全。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-21T15:00:00.000Z","url":"https://www.theverge.com/podcast/1038701/anthropic-ipo-ai-safety-openai-nvidia-structure"},{"id":"ufyn252g3i251j0mfwy8xth9r","title":"Anthropic 破纪录 IPO 未能止住 AI 抛售，全球股市下挫","summary":"Anthropic 上市第二天股价跌逾 9% 至 $88.17，接近 $83 发行价，其破纪录 IPO 未能止住 AI 相关公司抛售。周五 Nasdaq 跌 2%，SanDisk 跌 14%、Micron 跌 10%；亚洲股市创 2020 年以来最差一周，台湾加权指数跌 6.7%、日经跌 5%、Kospi 跌 5.5%，SoftBank 单日跌 14.5%。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-20T13:53:13.000Z","url":"https://www.theguardian.com/business/2026/nov/20/global-stock-markets-slump-anthropic-ipo-ai-sell-off"},{"id":"t3mx9fwmjqz97bj0zwxxtkkiq","title":"Anthropic 以 83 美元定价完成史上最大 IPO，上市首日估值近 2 万亿美元","summary":"Anthropic 以每股 83 美元在纳斯达克上市（代码 $ANT），融资 813 亿美元超过 SpaceX 成为史上最大 IPO，首日开盘价 111.50 美元、较发行价高 34.3%，完全稀释估值约 2 万亿美元。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-20T07:12:24.000Z","url":"https://latent.space/p/ainews-anthropic-successfully-completes-largest-ipo-in-history-valued-at-1-5t/"},{"id":"j96pobdmcb200kk2baf62615v","title":"Anthropic IPO 募资 813 亿美元创纪录，市值达 1.76 万亿美元引发安全争议","summary":"Anthropic 周四在纳斯达克上市，募资 813 亿美元，为史上最大 IPO，收盘市值 1.76 万亿美元，成为全球最大公共利益公司。CEO Dario Amodei 表示将按必要节奏推进 AI 训练与部署，不受商业或政治压力影响。","sourceName":"Platformer（热点 RSS）","firstParty":false,"publishedAt":"2026-11-20T01:37:44.000Z","url":"https://www.platformer.news/anthropic-goes-public/"},{"id":"hdvaqa4fp3ug2ozttf2n3tyuf","title":"Anthropic 七位创始人 IPO 套现近 20 亿美元，融资规模创纪录","summary":"Anthropic 上市融资 813 亿美元，其中七位创始人各出售约 340 万股，按 83 美元的发行价每人套现约 2.8 亿美元，合计 19.5 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T00:43:50.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-7-founders-cashed-out-nearly-2b-in-record-breaking-ipo/"},{"id":"k9l5dt0zbhvw3qiy58vzd95so","title":"Anthropic 纳斯达克上市首日收涨 17%，市值约 1.76 万亿美元","summary":"Anthropic 纳斯达克上市首日收于 97.17 美元、涨 17%，盘中一度较 83 美元发行价涨 38.7% 至 115.10 美元后回落。收盘完全稀释市值约 1.76 万亿美元，成为美国市值第 7 大公司；当日纳斯达克综合指数跌超 2%，部分散户卖出其他 AI 股套现认购新股。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T00:35:48.000Z","url":"https://x.com/rohanpaul_ai/status/2123576007282377061"},{"id":"e7xjysyuhq3nk3kvhci7lwx1c","title":"Anthropic 纳斯达克上市首日大涨 17%，市值达 1.27 万亿美元，IPO 募资 813 亿美元成史上最大","summary":"Anthropic 于 11 月 19 日在纳斯达克上市，首日收盘 97.17 美元，较 83 美元发行价上涨 17.07%，市值约 1.27 万亿美元。按 IPO 募资额计，本次募资 813 亿美元超过 SpaceX 6 月的 750 亿美元，为史上最大规模首次募股；公司每股收益为 -59.62 美元，尚未稳定盈利。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-19T22:41:40.427Z","url":"https://www.ithome.com/1/029/748.htm"},{"id":"dz0kkwkofq1dq1vzqqjgl0gyr","title":"Dario Amodei 谈丧父之痛与AI救人信念","summary":"Dario Amodei 分享说，他和妹妹、联合创始人 Daniela 的父亲因一种疾病去世，而那种病在他父亲去世仅几年后就变得可以治愈了。\n这份失去推动他投身生物学，也至今支撑着他的信念：AI 能让治愈更早到来。\n\n- Dario 是在当天纳斯达克开盘钟声前、于纳斯达克门前发表这番讲话的。\n\n----\n完整视频见“CNBC Television”YouTube 频道，（链接见评论）","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T21:15:23.000Z","url":"https://x.com/rohanpaul_ai/status/2123525569229078698"},{"id":"ps6iefgolixjza74xrxlf534q","title":"Anthropic IPO 开盘半小时下跌 13%，为 2008 年以来大型 IPO 最差开局","summary":"Gary Marcus 认为 Anthropic 的 IPO 看起来救不了低迷的科技行业。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-19T20:36:26.000Z","url":"https://garymarcus.substack.com/p/breaking-it-doesnt-look-anthropics"},{"id":"om8tbc6yznfxjsr25c29nb7mg","title":"WSJ：Anthropic IPO 定价 83 美元/股，或造约 600 名亿万美元级持股员工","summary":"WSJ 报道 Anthropic IPO 以每股 83 美元定价，估算约 600 名员工持股价值将超过 1 亿美元。该估算来自私募股权交易平台 Hill[.]com，其还预计约 2800 名员工持股超 1000 万美元，5000 多人的员工队伍中大多数人将超过 100 万美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T19:55:38.000Z","url":"https://x.com/rohanpaul_ai/status/2123505498419020007"},{"id":"b4uhmr8awqlofbouq18xga1qz","title":"Anthropic IPO 定价超出区间，开盘大涨 30%，市值一度达 2 万亿美元","summary":"Anthropic 完成 IPO，发行价超出区间且上调发行规模，开盘大涨 30%，市值一度达 2 万亿美元。文章称这是有史以来规模最大的 IPO（含私募配售），大幅超过 SpaceX，并指出此次上市还有多处罕见之处。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-19T19:36:02.000Z","url":"https://www.newcomer.co/p/anthropic-broke-all-the-startup-rules"},{"id":"he4xlj1y3ab1n3dfe8qvj3he9","title":"Anthropic IPO 慈善资金或达 1560 亿美元","summary":"TechCrunch 报道，Anthropic 上市后其公益基金 PBF 获配近 8.5 亿股（5%），按约 $95 股价约合 800 亿美元捐赠资金，估值较 $83 发行价每涨 50% 可再增持 2%。员工已认捐约 230 亿美元股票，公司按 3:1 或 1:1 配捐后总额约达 1560 亿美元，相当于 2025 年全美慈善捐款的四分之一，资金可能主要流向 AI 安全研究和 EA 相关慈善机构。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T19:10:45.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-ipo-could-deliver-156-billion-to-charity/"},{"id":"gp3hccimt42ak2uh82nrpty65","title":"indigo 转发 Dario Amodei 为 Anthropic IPO 在 Nasdaq 敲钟","summary":"indigo 转发 @YahooFinance 的画面，Dario Amodei 在 Nasdaq 为 Anthropic IPO 敲响开市钟。作者恭喜这家最\"人类\"的科技公司上市，并调侃其敲钟鼓掌的样子怎么像是 AI 生成的。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T17:14:14.000Z","url":"https://x.com/indigox/status/2123464879961186584"},{"id":"bj8r4lnrbcoi5cl1asnyn6qt5","title":"Anthropic CEO Dario Amodei 就公司 IPO 发表声明","summary":"Anthropic CEO Dario Amodei 就公司 IPO 发表声明，称今天让公司财务地位更稳固，并强调不会向商业或政治压力低头，将放慢 AI 训练与部署节奏以确保安全和人类可控。声明以生物学背景和 Claude 在科研中的应用为例阐述使命，同时承认滥用、经济冲击和失控等风险，倡导行业「向顶部竞赛」。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-19T17:01:26.000Z","url":"https://x.com/AnthropicAI/status/2123461658890686863"},{"id":"gklqioeodqeuqgz3lttg83ztv","title":"Anthropic 登陆纳斯达克，开盘价 111 美元较发行价高出 33%","summary":"Anthropic 在纳斯达克完成 IPO，开盘几分钟内股价达 111.50 美元，较 83 美元发行价高出 33%，发行价已超过公司此前 70 至 78 美元的预期区间。本次发行募资超过 810 亿美元，叠加同期私募融资后公司现金储备预计达 2200 亿美元；按开盘价计算市值超过 2 万亿美元，CEO Dario Amodei 在开盘致辞中强调公司对安全的承诺。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:59:23.000Z","url":"https://techcrunch.com/2026/11/19/anthropic-hits-nasdaq-exchanges-at-110-27-above-ipo-price/"},{"id":"rdgmufd2evohgemd2yh9qe2dy","title":"Anthropic 登陆纳斯达克，首日以 $111.50 开盘","summary":"Anthropic 正式在纳斯达克上市，代码 ANT，以 $111.50 开盘，高于 $83 的发行价，对应估值约 $1.5 万亿。其 S-1 文件披露上半年净亏损 $80.7 亿（主要来自不影响业务的会计费用）、营收 $16.3B，并保留创始人而非股东控制公司的治理结构；CEO Dario Amodei 表示将按需放缓 AI 训练与部署以确保安全，不屈服于商业或政治压力。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:52:01.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1035384/anthropic-ipo-trading-nasdaq"},{"id":"hzlbq0fxcls8sxek76qoq63v8","title":"Anthropic 股票上市首日开盘 111.50 美元，较 83 美元发行价涨约 34%","summary":"Anthropic 股票上市首日以每股 111.50 美元开盘，较每股 83 美元的 IPO 发行价上涨约 34%。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-19T16:51:39.000Z","url":"https://x.com/KateClarkTweets/status/2123459198390243417"},{"id":"ronlabq67u2qvt78d7o11k6c7","title":"Anthropic IPO 融资 810 亿美元后，八个思考看后续挑战","summary":"Alex Kantrowitz 在 Anthropic IPO 当天提出八点观察。Anthropic 此次发行 9.8 亿股、每股 83 美元，融资 810 亿美元，股价即将站上 100 美元，估值接近 2 万亿美元，成为史上最大 IPO。","sourceName":"Big Technology（热点 RSS）","firstParty":false,"publishedAt":"2026-11-19T16:48:08.000Z","url":"https://www.bigtechnology.com/p/eight-thoughts-on-anthropics-ipo"},{"id":"w5f6ldj9b4r2rde1v5ajx44p2","title":"Anthropic 完成史上最大规模 IPO，Dario Amodei 敲钟演讲重申放慢 AI 开发节奏","summary":"Anthropic 周四在纳斯达克完成号称史上最大规模 IPO 上市，CEO Dario Amodei 在敲钟演讲中重申将放慢 AI 训练与部署节奏，不受商业或政治压力影响，保持 AI 在人类控制之下。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:19:41.000Z","url":"https://techcrunch.com/2026/11/19/at-nasdaq-opening-bell-anthropic-ceo-recommits-to-pacing-ai-development/"},{"id":"wy4i94u2e6f4gl8p0fapqxcbg","title":"Anthropic CEO Dario Amodei 与联合创始人 Daniela Amodei 参与 Nasdaq 开市敲钟","summary":"Anthropic CEO Dario Amodei、联合创始人 Daniela Amodei 等参与了 Nasdaq 开市敲钟仪式，标志着史上最大规模 IPO 的开始。图片来源标注为 Michael Nagle/Bloomberg News。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T15:42:12.000Z","url":"https://x.com/rohanpaul_ai/status/2123441720214106148"},{"id":"mmwz8pv1im8uklob62bq34kii","title":"Anthropic 股票或以每股 104 美元开盘，高于 83 美元 IPO 定价约 25%","summary":"Anthropic 股票预计以每股 104 美元开盘，较 83 美元的 IPO 发行价高出约 25%。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-19T15:29:48.000Z","url":"https://x.com/KateClarkTweets/status/2123438598879871008"},{"id":"a8d06cpj4vy2dkdzazgsqsrwx","title":"Anthropic IPO 检验 AI 循环融资模式，Amazon 和 Google 持股市值约 3079 亿美元","summary":"TechCrunch 分析 Anthropic IPO 如何检验 AI 行业的循环融资模式。Amazon 14.7% 股份价值超 1590 亿美元，Google 13.7% 股份约 1490 亿美元；Nvidia、AMD、Microsoft、Broadcom、Micron、TSMC 还以 83 美元/股参与 260 亿美元私募。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:54:39.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-ipo-puts-ais-circular-financing-boom-to-the-test/"},{"id":"zs46vfwtzhs7fzho1p17mfisf","title":"Anthropic 完成史上最大规模 IPO，其安全治理结构受到审视","summary":"The Verge 报道 Anthropic 完成 IPO，募资 813 亿美元，超过 SpaceX 成为史上估值最高的上市，完全稀释市值约 1.5 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:25:37.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1037459/anthropic-ipo-safe-ai-reputation-power-structure"},{"id":"f26jfj074e12cy839qpuo6t1z","title":"Anthropic IPO 定价每股 83 美元募资 813 亿美元，超越 SpaceX 纪录","summary":"Anthropic IPO 定价每股 83 美元，高于 70 至 78 美元目标区间，募资 813 亿美元，超过 SpaceX 6 月创下的 750 亿美元纪录，股票周四以代码 ANT 在纳斯达克交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:02:22.000Z","url":"https://the-decoder.com/anthropics-81-3-billion-ipo-shatters-spacexs-record-as-rising-rates-and-political-headwinds-shake-the-sector/"},{"id":"yu2rsdalw8maktdgtkdxou91v","title":"推文建议Claude订阅用户买入Anthropic股票","summary":"该推文建议Claude订阅用户成为Anthropic股东，称$ANT IPO价格为每股83美金。作者算账：Ultra订户一年2400美金、十年24000美金，约买250股，十年回报可覆盖全部订阅费且大概率盈利，并称十万亿市值应是十年后科技巨头入门标准。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T02:13:37.000Z","url":"https://x.com/indigox/status/2123238235526877663"},{"id":"c2a172rbdidbvyqk87irlvoba","title":"indigo 建议 Claude 订阅用户在 $ANT IPO 每股 83 美金时买入约 250 股覆盖订阅成本","summary":"indigo 建议 Claude 订阅用户买入 Anthropic 股票，成为公司股东。他提到 $ANT 次日 IPO 定价每股 83 美金，Ultra 订户一年成本 2400 美金、十年 24000 美金，购入约 250 股十年后的回报可覆盖全部订阅费并大概率盈利，并认为十年后十万亿市值将是科技巨头的入门标准。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T02:08:37.000Z","url":"https://x.com/indigox/status/2123236975780241812"},{"id":"am0vdstva0f00mrpzw0stslkw","title":"Anthropic IPO 定价每股 83 美元，发行 9.8 亿股 A 类股募资约 813 亿美元","summary":"Anthropic 以每股 83 美元定价 IPO，高于区间顶部 6%，发行 9.8 亿股 Class A 普通股，总募资约 813 亿美元，预计次日登陆纳斯达克。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T00:15:51.000Z","url":"https://x.com/rohanpaul_ai/status/2123208597303885970"},{"id":"x57gypzdz09onwjnccctd484i","title":"Anthropic IPO 定价 83 美元一股，即将登陆 Nasdaq","summary":"Anthropic 宣布 IPO 定价 83 美元/股，预计明日开始在 Nasdaq 交易。招股书由 SEC 于 2026 年 11 月 18 日宣布生效，承销方包括 Goldman Sachs 和 Morgan Stanley，公告原文见 anthropic.com。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-18T23:38:05.000Z","url":"https://x.com/indigox/status/2123199094680351131"},{"id":"hokjlogeo9373uw76eeb3f3mh","title":"Anthropic 将 IPO 定价定为每股 83 美元，明日登陆纳斯达克","summary":"Anthropic 宣布 IPO 定价为每股 83 美元，交易预计次日在纳斯达克开始。其 Class A 普通股注册声明已于 2026 年 11 月 18 日获 SEC 生效，本次发行仅通过招股说明书进行，承销方包括 Goldman Sachs 与 Morgan Stanley。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-18T23:29:00.000Z","url":"https://x.com/AnthropicAI/status/2123196808675405860"},{"id":"gltv70anlfz4zx6b9guzvq43l","title":"Anthropic IPO 定价每股 $83，募资总额超 $94B 创纪录","summary":"Anthropic 将 IPO 定价定为每股 $83，高于 $70–$78 区间上沿 6.4%，报道称认购订单达发行股份的最多 6 倍，约 20% 份额留给散户（通常为 5%–10%）。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-18T22:37:43.000Z","url":"https://x.com/rohanpaul_ai/status/2123183901799846133"},{"id":"fbmacbdd7mkfush2x2wjfrpvy","title":"Anthropic 以每股 83 美元定价 IPO，估值达 1.5 万亿美元","summary":"Anthropic 据报道将 IPO 定价定为每股 83 美元，高于 70 至 78 美元的初始区间，完全稀释估值达 1.5 万亿美元，将于周四在纳斯达克以代码 ANT 上市。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-18T22:11:15.000Z","url":"https://techcrunch.com/2026/11/18/anthropic-reportedly-prices-ipo-at-83-a-share-above-projected-range/"},{"id":"kb0qscktovse2ejle2ubpcr2z","title":"Anthropic IPO 定价 83 美元，高于发行区间","summary":"Anthropic IPO 定价为每股 83 美元，高于此前发行区间。消息援引自 WSJ 报道。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-18T21:41:58.000Z","url":"https://x.com/KateClarkTweets/status/2123169870552436802"},{"id":"jpjly30jyb7nf4muyzc0tc8fo","title":"Understanding AI 用19张图表解析AI行业现状","summary":"Understanding AI 发布19张图表，量化AI对美国经济和就业的影响。文中提到 Anthropic 即将上市，估值或超万亿美元，OpenAI 预计明年跟进；五大科技公司2026年第三季度资本支出达2300亿美元，AI收入年化运行率达3450亿美元，但新增企业采用放缓，年轻软件工程师就业明显下滑。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-11-18T21:34:00.000Z","url":"https://www.understandingai.org/p/19-charts-that-explain-the-state"},{"id":"mlkeroda115hl0tiwrzs8njih","title":"Every 团队实测：我们让 AI 智能体买什么，什么时候仍坚持自己按下“购买”","summary":"ChatGPT 上周获得钱包功能后，Every 团队实测了让 AI 智能体代买杂货、机票等物品的体验，并讨论了哪些场景仍坚持自己按下“购买”。同期，Anthropic 在纳斯达克上市，开盘价 $111.50，市值 $2 万亿，募资 $81 亿，成为首家上市的前沿 AI 实验室。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-11-18T16:00:00.000Z","url":"https://every.to/context-window/what-we-let-our-agents-buy"},{"id":"yxu549lhmsyp0qe8rstrheqlw","title":"Anthropic IPO 估值最高或达 1.4 万亿美元，华尔街提前造势散户争抢","summary":"据路透社报道，Anthropic 预计于当地时间 11 月 19 日登陆公开市场，IPO 估值最高可能达到 1.4 万亿美元。金融机构已推出 2 倍做多与做空 ETF 等挂钩产品，Vanda Research 预计上市将吸引约 2.5 亿美元散户净买入，为 SpaceX IPO 期间 1.18 亿美元纪录的两倍。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-18T10:45:07.760Z","url":"https://www.ithome.com/1/029/015.htm"},{"id":"hpczcbqe8agr7jffko2cnsp31","title":"Anthropic 拟将 IPO 定价上调至 $80 以上，估值或达 $1.6T","summary":"据 WSJ，Anthropic 预计将 IPO 定价上调至 $70 至 $78 区间之上，可能超过 $80 一股，其顾问已讨论 $1.5T 或 $1.6T 的估值，高于此前约 $1.33T。按申报区间计算，IPO 规模约 $61B，另有 $26B 私募配售，其中 Google 和 Nvidia 各以 IPO 价格认购约 $10B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-18T00:15:01.000Z","url":"https://x.com/rohanpaul_ai/status/2122845999387602999"},{"id":"cxpq4gwitsj6r05zjpphx9agc","title":"Anthropic 获准在纳斯达克上市，代码 ANT，发行价每股 70~78 美元","summary":"根据 SEC 11 月 17 日公示的文件，Anthropic 的 A 类普通股获准在纳斯达克全球精选市场上市，代码 ANT，发行价区间维持每股 70 至 78 美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-18T00:12:10.273Z","url":"https://www.ithome.com/1/028/599.htm"},{"id":"h9i8o2kzwr1fj3op3i48gcyhb","title":"Anthropic IPO 后 Amazon 与 Google 将合计持股近 30%","summary":"Anthropic 披露 IPO 相关投资细节：Amazon 持股将达 14.7%，全部转换可转债可至 23.8%；Google 持股 13.7%，均为无投票权股份。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-17T22:29:05.000Z","url":"https://techcrunch.com/2026/11/17/amazon-and-google-will-together-own-nearly-30-of-anthropic-after-its-ipo/"},{"id":"mqb1ivb69ry2hmuc65xst4mle","title":"Anthropic 因投资者需求旺盛计划上调 IPO 发行价","summary":"记者 Kate Clark 引述 WSJ 报道，Nvidia 相关风波并未拖慢 Anthropic 的 IPO 进程，由于投资者需求旺盛，公司计划上调发行价。报道由 Kate Clark 与 WSJ 记者 @cdriebusch、@BenDummett 合作完成。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-17T17:04:26.000Z","url":"https://x.com/KateClarkTweets/status/2122737640306884838"},{"id":"o0z8uukw36ic6txpxi29o96ep","title":"Anthropic IPO 定价每股 $83.00，11 月 19 日以代码 ANT 登陆纳斯达克","summary":"Anthropic, PBC 宣布其 IPO 定价为每股 $83.00，共发行 980,000,000 股 Class A 普通股，其中 956,351,354 股由公司出售，23,648,646 股由部分出售股东出售，公司不会获得后者收益。","sourceName":"Anthropic：Newsroom（网页）","firstParty":true,"publishedAt":"2026-11-17T16:00:00.000Z","url":"https://www.anthropic.com/news/anthropic-prices-initial-public-offering"},{"id":"g00g4zgmnmxgh069cxc07h5ko","title":"FT：SBF 投入 Anthropic 的 5 亿美元按 IPO 预期价格约值 370 亿美元","summary":"据 FT，Sam Bankman-Fried 当年投入 Anthropic 的 5 亿美元，按下周预期 IPO 价格约值 370 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T00:31:20.000Z","url":"https://x.com/rohanpaul_ai/status/2121400552927985769"},{"id":"zqbqdxdjvxdhrl7z9zzwvi9qa","title":"多家银行以美国出口管制为由，拒绝中国大陆和香港投资者参与 Anthropic IPO","summary":"据 Bloomberg 报道，多家银行拒绝中国大陆和香港投资者的认购订单，或认为其获配可能性很低，部分人士以美国出口管制规则 ITAR 为由。Anthropic 不予置评，此次 IPO 由 Goldman Sachs 和 Morgan Stanley 牵头，另有 20 家银行参与，股票预计 11 月 18 日定价后在 Nasdaq 以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:01:53.000Z","url":"https://the-decoder.com/banks-bar-chinese-and-hong-kong-investors-from-anthropic-ipo-over-us-export-controls/"},{"id":"ir04ccbh63mo2xavryooeewvr","title":"Anthropic IPO 获六倍超额认购，有望成史上最大规模 IPO","summary":"据 Bloomberg 报道，Anthropic 的 IPO 订单超出可售股份六倍，公司及其联合创始人拟通过公开发行募资至多 644 亿美元，另通过私募募资 260 亿美元，目标估值约 1.4 万亿美元，若达成将超过 SpaceX 的 IPO。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:15:08.000Z","url":"https://the-decoder.com/anthropics-ipo-is-six-times-oversubscribed-and-on-track-to-become-the-largest-public-offering-in-history/"},{"id":"k99zjo9hbtous9r6vmmz7pxyh","title":"Anthropic 官宣首次公开募股（IPO）","summary":"Anthropic 官方宣布启动首次公开募股（IPO），并公布入口 ipo.anthropic.com。Anthropic 已向 SEC 提交注册声明及招股说明书，证券在注册声明生效前不得出售，初步招股说明书可经高盛与摩根士丹利获取。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-12T11:30:46.000Z","url":"https://x.com/AnthropicAI/status/2120841731302154708"},{"id":"xi0y19pbadxpvgcmzsm7c5byg","title":"Anthropic IPO 路演视频披露多芯片策略与算力乘数细节","summary":"Simon Willison 整理了 Anthropic IPO 路演视频的转录稿，称其中包含此前未公开的业务信息。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T15:11:59.000Z","url":"https://simonwillison.net/2026/Nov/11/anthropic-ipo-roadshow/"},{"id":"r5kn7uexy6jx97qwxwvnpqrom","title":"Anthropic IPO 拟募资最高 90.4B 美元，或成史上最大上市","summary":"Bloomberg 报道 Anthropic IPO 已获数倍于发行份额的订单，主要来自大型机构投资者的锚定级意向。公司通过 IPO 加私募配售寻求最高 $90.4B，将超过 SpaceX 的 $85.7B 纪录成为史上最大上市，完全稀释估值目标约 $1.4T；Goldman Sachs 和 Morgan Stanley 牵头共 22 家银行，股票将以 ANT 在纳斯达克全球精选市场交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T14:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2120526677247939001"},{"id":"ajjv9abs8vd20j05emcig98ai","title":"WSJ：Anthropic 7 位创始人 IPO 各套现约 2.5 亿美元并保留控制权","summary":"WSJ 报道，Anthropic 7 位创始人将在 IPO 中各出售约 2.5 亿美元股票，每人保留约 180 亿美元持仓。据公司文件，每人出售近 3.4M 股，发行价区间预计 70 至 78 美元，上市预计下周进行，估值接近 1.3 万亿美元，募资 800 亿美元以上，部分通过包括 Google 在内的私募配售。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:47:04.000Z","url":"https://x.com/rohanpaul_ai/status/2120392847505715324"}]},"99a822a0-0b83-4aff-8f65-02c408205578":{"publicId":"99a822a0-0b83-4aff-8f65-02c408205578","title":"杨立昆指阿莫迪炒作AI危险论，阿莫迪否认","status":"active","sourceCount":4,"reportCount":4,"firstReportAt":"2026-11-25T02:16:31.833Z","latestAt":"2026-11-25T20:15:50.000Z","latest":"Anthropic CEO Dario Amodei 称把社会治理交给 AI 是个坏主意","digest":"Meta 首席 AI 科学家杨立昆在 X 发文，指责 Anthropic CEO 达里奥·阿莫迪自 GPT-2 发布以来一直炒作 AI 危险性，目的是推动开源模型被列为非法、让自己掌握控制权；他还称阿莫迪离开 OpenAI 只是因为在那里无法掌握控制权，并将这种做法比作奥斯曼帝国禁止阿拉伯语印刷机。上述说法均出自杨立昆本人。\n\n阿莫迪随后在 X 发长文回应，否认自己主张把人类自由意志交给 AI，称这一指控荒谬，并重申人类应保留最终决策权、AI 须受合法民主程序治理。他同时区分治理之争与任务自动化之争，并提议以递归自我改进（RSI）作为划线点。\n\n阿莫迪的回应针对 Axios 一篇援引知情人士、涉及 Anthropic 内部讨论的报道。他称政治决策应留在人类手中，并认为反对比拒绝独裁更强。这些均为阿莫迪本人的说法。","digestUpdatedAt":"2026-11-25T20:27:02.575Z","reports":[{"id":"zw6z5pavhs3ogid1zm14nu1xi","title":"Anthropic CEO Dario Amodei 称把社会治理交给 AI 是个坏主意","summary":"Anthropic CEO Dario Amodei 在 X 长文回应 Axios 报道，称认为人类应向 AI 交出自由意志的说法荒谬，AI 必须受合法民主程序治理，政治决策应留在人类手中，反对比拒绝独裁更强。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-25T20:15:50.000Z","url":"https://the-decoder.com/anthropic-ceo-dario-amodei-says-letting-ai-govern-society-would-be-a-bad-idea/"},{"id":"fndlzxrjx5yxnikuebfn0mawg","title":"Dario Amodei 回应移交人类控制权指控，称其说法荒谬","summary":"Anthropic CEO Dario Amodei 在 X 长文回应对 Anthropic 主张向 AI 交出人类自由意志的指控，称其荒谬，重申人类应保留最终决策权，并提议以递归自我改进（RSI）作为划线点。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-25T19:44:24.000Z","url":"https://techcrunch.com/2026/11/25/anthropics-dario-amodei-calls-accusations-of-surrendering-human-control-to-ai-absurd/"},{"id":"mcfwxrky5x44lthhyycpbc0hy","title":"Dario Amodei 澄清立场：反对把人类自由意志交给 AI，并区分治理与任务自动化之争","summary":"Dario Amodei 回应 Axios 报道，否认自己主张向 AI 系统交出人类自由意志，重申在其多篇文章中一贯主张 AI 须受合法民主程序治理。","sourceName":"X：Dario Amodei (@DarioAmodei)","firstParty":false,"publishedAt":"2026-11-25T18:22:33.000Z","url":"https://x.com/DarioAmodei/status/2125656399392690605"},{"id":"pek2b96neq296ir8cwaw8s7eo","title":"杨立昆怒怼 Anthropic CEO 阿莫迪：炒作 AI 危险论是为了掌握控制权","summary":"杨立昆在 X 平台发文怒怼 Anthropic CEO 达里奥·阿莫迪，称其自 GPT-2 以来一直炒作 AI 的危险性，目的是让开源模型被列为非法、让自己掌握控制权，并称他离开 OpenAI 只是因为在那里无法掌握控制权。他将这种做法比作奥斯曼帝国禁止阿拉伯语印刷机，是一种新的中世纪蒙昧主义，阻止人们自由获取多元知识。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-25T02:16:31.833Z","url":"https://www.ithome.com/1/031/960.htm"}]},"c38b8a26-309e-4ed2-841e-c4821cf589fe":{"publicId":"c38b8a26-309e-4ed2-841e-c4821cf589fe","title":"Anthropic 将 Claude Messages API 从 Python 迁至 Rust","status":"active","sourceCount":6,"reportCount":6,"firstReportAt":"2026-11-24T16:00:00.000Z","latestAt":"2026-11-25T20:52:14.000Z","latest":"Anthropic 将 Messages API 从 Python 迁移到 Rust，每请求 CPU 降低约 70%","digest":"Anthropic 称已将 Claude Messages API 从 Python 迁移到 Rust，并把原有 Python 服务当作校验基准：用生产流量测试新版本，由多组 Claude 智能体追踪并修复两个版本之间的差异，直到 Rust 版本与生产环境的可观察行为一致。\n\n据 Anthropic 工程博客，该 API 流量从 2024 年初到 2026 年秋增长约 1800 倍；迁移后每请求 CPU 降低约 70%，首 token 中位时间缩短约 20%，期间未停服，也未冻结功能开发。上述效果数据均出自 Anthropic 自述。\n\nRohan Paul 的转述补充称，Claude 约一周写出 Rust 初稿，但让新版本行为与 Python 完全一致更难，验证环节才是主要工作量。","digestUpdatedAt":"2026-11-25T22:07:28.066Z","reports":[{"id":"ro9d102qwfkzisnd7ppd8wex8","title":"Anthropic 将 Messages API 从 Python 迁移到 Rust，每请求 CPU 降低约 70%","summary":"Anthropic 分享了把 Messages API 从 Python 迁移到 Rust 的工程实践，每个请求的 CPU 使用降低约 70%。API 流量自 2024 年初以来增长约 1,800 倍，Claude 用约一周写出 Rust 初稿，但验证行为与 Python 完全一致更难，团队用多个 Claude 智能体追踪并修复两个版本之间的差异。详见 https://www.anthropic.com/research/migrating-api-to-rust。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-25T20:52:14.000Z","url":"https://x.com/rohanpaul_ai/status/2125694070748311778"},{"id":"rnanzlnaqxdr2icjqw0qwv9la","title":"Anthropic 平台工程负责人 Katelyn Lesse 谈 2026 年如何用 Claude 构建软件","summary":"Pragmatic Engineer 发布对 Anthropic 平台工程负责人 Katelyn Lesse 的播客访谈，她团队负责 Claude API 及 Claude Code 和 Claude Desktop 的基础设施。","sourceName":"Pragmatic Engineer（RSS）","firstParty":false,"publishedAt":"2026-11-25T17:31:32.000Z","url":"https://newsletter.pragmaticengineer.com/p/how-anthropic-builds-software-in"},{"id":"jroy52o4ksmyxj75h7rksyoqb","title":"Anthropic 分享将 Claude Messages API 从 Python 迁移到 Rust 的工程方法","summary":"Anthropic 工程师称团队已将 Claude Messages API 从 Python 迁移到 Rust，并发布工程博客（anthropic.com/research/migrating-api-to-rust）介绍做法。方法上把 Python API 当作 oracle，搭建验证循环，由一组智能体不断修复 diff，直到 Rust 版本与生产环境的可观察行为一致；Ado Kukic 转发了这篇博客。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-25T17:29:46.000Z","url":"https://x.com/adocomplete/status/2125643118523646092"},{"id":"lapixfybsntxaufwpjn22aj5w","title":"Claude Messages API 从 Python 迁移至 Rust","summary":"我们的新工程博客分享了如何将 Claude Messages API 从 Python 迁移到 Rust。\n\n我们分享了如何利用现有的 Python 服务来验证此次迁移，由多个智能体团队追踪并修复两个版本之间的差异。\n\nhttps://x.com/AnthropicAI/status/2125627317263466739?a=cMWx_Moml5Tb3-Enk4A&s=20","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-25T16:32:33.000Z","url":"https://x.com/ClaudeDevs/status/2125628717263372512"},{"id":"w3w7s7ng7nmsqmv6x5fcdqfkq","title":"Anthropic 分享 Messages API 从 Python 迁移到 Rust 的工程实践","summary":"Anthropic 官方宣布其 Messages API 已从 Python 迁移到 Rust，并在工程博客 https://www.anthropic.com/research/migrating-api-to-rust 分享迁移过程。团队用现有服务对新服务进行验证，由多组 Claude 智能体追踪并修复两个版本之间的差异。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-25T16:26:59.000Z","url":"https://x.com/AnthropicAI/status/2125627317263466739"},{"id":"h1ja45355xx1xf9rqf89cv1if","title":"Anthropic 复盘 Messages API 从 Python 迁移到 Rust 的校验方法","summary":"Anthropic 介绍如何将 Messages API 从 Python 迁移到 Rust，并把生产系统本身当作校验器。该 API 流量从 2024 年初到 2026 年秋增长约 1800 倍，迁移后每请求 CPU 降低约 70%，首 token 中位时间缩短约 20%，且未停服或冻结功能开发。","sourceName":"Anthropic：Research（发表成果 · 网页）","firstParty":true,"publishedAt":"2026-11-24T16:00:00.000Z","url":"https://www.anthropic.com/research/migrating-api-to-rust"}]},"f78e26b9-cf3c-4b28-9761-bdfcbc5eb283":{"publicId":"f78e26b9-cf3c-4b28-9761-bdfcbc5eb283","title":"Thariq宣布从Anthropic离职并加入OpenAI","status":"active","sourceCount":2,"reportCount":2,"firstReportAt":"2026-11-25T21:33:32.000Z","latestAt":"2026-11-25T22:28:01.000Z","latest":"OpenAI 的 Thariq Shihipar 谈编程智能体时代的“革命与文艺复兴”","digest":"Thariq（@trq212）宣布已从Anthropic离职、加入OpenAI。他在声明中称，自己为在Anthropic的时光感到自豪，会继续支持前同事，并认为两家公司都将在AI未来扮演重要角色。\n\nThariq表示，他期待在OpenAI为超过10亿用户打造AI产品，并与@_catwu、@thsottiaux等人共事。上述说法均来自他本人的公开声明。\n\n在AI Engineer CODE演讲中，Thariq Shihipar演示了用编程智能体批量生成软件与打磨单件作品可以并存，并谈到决策模型如何从设计师定义的动作中选择、谁来决定哪些实验值得投入算力。他在录制该演讲后宣布加入OpenAI。","digestUpdatedAt":"2026-11-25T22:57:11.228Z","reports":[{"id":"vd0mls76sn4993nxmfpymvlgh","title":"OpenAI 的 Thariq Shihipar 谈编程智能体时代的“革命与文艺复兴”","summary":"在 AI Engineer CODE 演讲中，Thariq Shihipar 演示了用编程智能体批量生成软件与打磨单件作品可以并存：他在 /human 文件夹里改一块石头的尺寸后立刻试投掷，也做过一个可切换模式的 Mac Dock。他谈到自己因编程智能体改变了哪些看法、决策模型如何从设计师定义的动作中选择，以及谁来决定哪些实验值得投入算力。他在录制后宣布加入 OpenAI。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-25T22:28:01.000Z","url":"https://latent.space/p/the_revolution_vs_the_renaissance_thariq_shihipar_openai/"},{"id":"llkxscqvja6f243nxpeue7e36","title":"Thariq 宣布从 Anthropic 加入 OpenAI","summary":"Thariq（@trq212）宣布加入 OpenAI。他表示为在 Anthropic 的时光自豪、会继续支持前同事，认为两家公司都将在 AI 未来扮演重要角色；他期待在 OpenAI 为超 10 亿用户打造 AI 产品，并与 @_catwu、@thsottiaux 等人共事。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-25T21:33:32.000Z","url":"https://x.com/rohanpaul_ai/status/2125704462153257074"}]},"9474636b-5271-405b-91d7-b469bdf1aa8f":{"publicId":"9474636b-5271-405b-91d7-b469bdf1aa8f","title":"Anthropic 发布 Claude Ship 测试版，自动审查并批准 PR","status":"active","sourceCount":13,"reportCount":19,"firstReportAt":"2026-11-23T00:00:00.000Z","latestAt":"2026-11-25T07:30:08.000Z","latest":"Claude Code 团队发布实用指南讲解 Claude Ship 的 PR 审查与守护用法","digest":"Anthropic 发布 Claude Ship 测试版，让 Claude 审查 pull request、处理修复，并按团队策略批准可合并的改动。它由三部分组成：Code Review 已正式可用，PR Steward 和 Claude Approvals 两个智能体处于 beta；前者处理失败的 CI 检查、合并冲突和审查反馈，后者在政策允许时批准常规改动。\n\nClaude Ship 面向 Claude Team 和 Enterprise 计划、GitHub 仓库开放，不适用于启用 Zero Data Retention、HIPAA 配置或客户自管密钥的组织。管理员可按仓库开启，团队 PR 无需运行 /ship 即可自动运行；审批策略以仓库中的 .claude/approvals.yml 配置。Anthropic 建议先以 observe 模式运行审批，并称符合条件的 Enterprise 组织可在 2027 年 1 月 15 日前申领至少 1 万美元额度，费用按 token 计。The Decoder 称 PR Steward 默认没有支出上限，团队需自行设置预算。\n\nClaude Code 同时推出 /ship 命令，正在 CLI 和桌面应用中逐步开放，任何人都可使用。合并最终仍由用户权限和分支规则决定；Claude Ship 使用 AI，可能遗漏 bug 或安全问题。","digestUpdatedAt":"2026-11-25T07:36:27.899Z","reports":[{"id":"uyodjb16jngloilypsm1d3q0d","title":"Claude Code 团队发布实用指南讲解 Claude Ship 的 PR 审查与守护用法","summary":"Anthropic Claude Code 团队刚推出 Claude Ship，包含三个智能体：Code Review（已全面开放）、PR Steward 和 Claude Approvals（beta），可审查 PR、处理失败 CI、合并冲突和审查意见，并按仓库策略文件批准常规改动。","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-25T07:30:08.000Z","url":"https://x.com/addyosmani/status/2125492213903978917"},{"id":"ipcqjvmnwr18xgxpmk7f7pzl7","title":"Claude Code 实用指南：PR 后续交给 Claude Ship","summary":"Claude Code 实用交付指南：如何把 PR 后续跟进工作交给 Claude Ship，并保持工作流不中断。\n\nhttps://claude.dev/blog/the-work-after-you-open-a-pr/","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-24T23:07:17.000Z","url":"https://x.com/ClaudeDevs/status/2125365668463993091"},{"id":"xhwdnk4oemxxrx812hufd0beg","title":"Claude Code 团队实践指南：如何用 Claude Ship 处理开 PR 后的跟进工作","summary":"Claude Code 团队的 Addy Osmani 撰文介绍如何在新近随 Claude Ship 上线的功能基础上，搭建开 PR 后的智能体跟进流程。","sourceName":"Anthropic：Claude.dev 开发者博客（RSS）","firstParty":true,"publishedAt":"2026-11-24T12:00:00.000Z","url":"https://claude.dev/blog/the-work-after-you-open-a-pr/"},{"id":"f9j5sn8oacg4jjy5ajb9vu6r5","title":"Anthropic 推出 Claude Ship beta，AI 智能体可自主审查、修复并审批 PR","summary":"Anthropic 推出 beta 版 Claude Ship，组合已有的 Code Review 与两个新智能体 PR Steward 和 Claude Approvals，可自动审查代码变更、修复问题并按团队策略审批合并。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-24T11:26:23.000Z","url":"https://the-decoder.com/anthropics-claude-ship-lets-ai-agents-review-fix-and-approve-pull-requests-on-their-own/"},{"id":"h0cco60oiwe37arv7x3pdupj9","title":"Anthropic 发布 Claude Ship 覆盖 GitHub PR 审查与修复","summary":"Anthropic 发布 Claude Ship，一套覆盖 GitHub PR 从审查到批准的智能体，包含 Code Review、PR Steward 和 Claude Approvals，其中 Code Review 已正式可用，另外两个处于公测。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-24T00:02:39.000Z","url":"https://www.marktechpost.com/2026/11/23/anthropic-claude-ship-pull-request-agents/"},{"id":"lxyhdhyjwd5qp8w3jo3pfvg3l","title":"Anthropic 推出 Claude Ship 测试版：AI 自动完成代码审查、修复与批准","summary":"Anthropic 推出 Claude Ship Beta 测试版，一套 AI 智能体工具，可自动完成代码审查、修复和批准。其包含 Code Review、PR Steward 和 Claude Approvals 三项功能，Code Review 已正式开放，后两项处于 Beta 阶段。Anthropic 建议团队先以观察模式运行审批功能，并可在单个仓库启用、设置每月支出上限。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T23:49:00.083Z","url":"https://www.ithome.com/1/031/257.htm"},{"id":"cf7exc2q4r0gpagip2rcepyy2","title":"Anthropic 推出 Claude Ship beta，自动审查并按策略审批 PR","summary":"Anthropic 的 ClaudeDevs 发布 Claude Ship（beta），Claude 可审查 pull request、修复问题，并按团队策略允许的范围自动批准。作者补充称它覆盖从 review 到自动审批的 PR 全生命周期，帮助承接各种编码工具带来的 PR 吞吐量。","sourceName":"X：Noah Zweben（@noahzweben）","firstParty":false,"publishedAt":"2026-11-23T22:25:45.000Z","url":"https://x.com/noahzweben/status/2124992828996768156"},{"id":"mlop8hozs26imcfjayymd6vn9","title":"Anthropic 发布 Claude Ship，让 AI Agent 审查、修复并审批代码变更","summary":"Anthropic 发布 Claude Ship，一组用于自动化代码审查、修复和审批的 AI Agent。其中 Code Review 已正式可用，PR Steward 和 Claude Approvals 处于 beta，后者可按团队以自然语言写入仓库的审批策略自动批准变更。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T22:05:50.000Z","url":"https://techcrunch.com/2026/11/23/anthropic-launches-claude-ship-letting-ai-agents-review-fix-and-approve-code-changes/"},{"id":"mo9ri8nex517xyijhdw83ywnb","title":"Claude Ship (beta) 发布：审查 PR、修复问题并按团队策略批准","summary":"Anthropic 官方 @ClaudeDevs 宣布推出 Claude Ship (beta)：Claude 可以审查你的 pull request、参与修复，并批准团队策略允许的合并，目标是让代码能按你写出来的速度交付。作者 Lydiahallie 作为 Claude Code 团队成员转发并配上 /ship 🚢。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-23T20:48:44.000Z","url":"https://x.com/lydiahallie/status/2124968415316361462"},{"id":"pa7y6lb03wza7cwwikew64sqr","title":"Anthropic 推出 Claude Ship 公测：可审查 PR、修复问题并按策略审批","summary":"Anthropic 推出 Claude Ship（beta），Claude 可以审查 pull request、参与修复，并批准团队策略允许的 PR。目标是帮助开发者以接近书写代码的速度交付代码。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-23T20:24:59.000Z","url":"https://x.com/adocomplete/status/2124962436029841746"},{"id":"ape2l2bmhd99j8ql1myg113yb","title":"Claude Code 推出 /ship 与 Claude Ship 功能，Team 和 Enterprise 可按 repo 开通","summary":"Boris Cherny 介绍 Claude Ship 功能：任何人可使用 /ship，Team 或 Enterprise 计划的管理员可按 GitHub repo 开通 Claude Ship。他建议先从一个 repo 开始，在信任建立前让 Approvals 以 observe 模式运行，并附介绍文章链接 claude.com/resources/articles/introducing-claude-ship。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:13.000Z","url":"https://x.com/bcherny/status/2124961488691740941"},{"id":"da9x2u8i3q7gwi3tbyynwlo7k","title":"Boris Cherny 介绍 Claude Code 的 Code Review、PR Steward 与 Claude Approvals 功能","summary":"Boris Cherny 介绍 Claude Code 新增的代码审查与 PR 工作流功能，称其成倍提升自己的开发速度，无需等待 code review 或盯着 PR，结果也更好。具体包括查找 bug 的 Code Review、处理修复和失败检查的 PR Steward，以及按团队策略批准的 Claude Approvals，后两者处于 beta 阶段。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:13.000Z","url":"https://x.com/bcherny/status/2124961487454384442"},{"id":"bogrl7sijta9kbxqrgfy7hz10","title":"Anthropic 推出 Claude Ship beta：可审查 PR、修复代码并按团队策略批准合并","summary":"Boris Cherny 宣布面向 Team 和 Enterprise 推出 Claude Ship（beta），用于弥补写代码与发布 PR 之间的落差。Claude Ship 可以审查 pull request、处理修复，并批准团队策略允许的合并，目标是让发布代码的速度跟上写代码的速度。作者称自己每天都在使用。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:12.000Z","url":"https://x.com/bcherny/status/2124961485801836573"},{"id":"oom14bdotou4ycx1qqm0kwway","title":"Anthropic Claude Code 团队推出 Claude Ship，自动处理 PR 审查、修复与审批","summary":"Claude Code 团队推出 Claude Ship（beta），可将 PR 走完审查、修复和基于团队策略的审批决策。","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-23T20:16:08.000Z","url":"https://x.com/addyosmani/status/2124960211287101656"},{"id":"abjvysdchmlsi68fbinr7orat","title":"Claude Ship 支持 Team 与 Enterprise 管理员按仓库启用自动审批","summary":"Claude Ship 在 Team 和 Enterprise 计划中支持管理员为整个仓库开启，团队 PR 无需 /ship 即可自动运行。审批策略以 .claude/approvals.yml 文件形式存放在仓库中，可配置通过人数、路径规则和 Claude 审核通过后的覆盖判定，作用类似更智能的 CODEOWNERS 文件。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:05.000Z","url":"https://x.com/ClaudeDevs/status/2124959440772137337"},{"id":"b8e3upoinqevs0u08u79ckn3o","title":"Claude Code 推出 /ship 命令，自动开 PR 并跟进审查与修复","summary":"Anthropic 的 Claude Code 推出 /ship 命令，正在 CLI 和桌面应用中逐步开放，可让 Claude 打开 PR、审查改动并处理反馈和失败的检查。图片展示 Review、Fix（PR Steward，BETA）、Approve（Claude Approvals，BETA）三个环节的流程，最终在团队策略下达到 Ready to merge，并提示 Claude Ship 使用 AI、可能遗漏 bug 或安全问题。合并仍由用户的权限和分支规则决定。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:04.000Z","url":"https://x.com/ClaudeDevs/status/2124959438175981965"},{"id":"gt4d8yrshukcau05h4zsfrmpc","title":"Anthropic 推出 Claude Ship 测试版，可审查 PR 并按团队策略批准","summary":"Anthropic 推出 Claude Ship（beta），Claude 可审查 pull request、着手修复问题，并批准符合团队策略的部分。目标是帮助开发者以写代码的速度更快发布。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:04.000Z","url":"https://x.com/ClaudeDevs/status/2124959436640858475"},{"id":"sy80jk76lkvjtf63d6v5xncpi","title":"Anthropic 推出 Claude Ship，可自动审查并合入 PR","summary":"Anthropic 发布 Claude Ship，让 Claude 能审查、修复并批准 pull request。其中 PR Steward 和 Claude Approvals 两个智能体以 beta 形式上线，前者处理失败的 CI 检查、合并冲突和审查反馈并留言说明改动，后者在组织政策允许时可批准常规改动。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T20:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1040134/anthropic-claude-ship-ai-pull-requests"},{"id":"t7jlbaldqf2zcliuva1sofoks","title":"Anthropic 推出 Claude Ship 测试版，自动完成 PR 审查、修复与审批","summary":"Anthropic 发布 Claude Ship 测试版，由 Code Review（已正式可用）、PR Steward 和 Claude Approvals 两个 beta 智能体组成，可审查 PR、推送修复并按团队写进仓库的策略文件决定能否合并。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-23T00:00:00.000Z","url":"https://claude.com/blog/introducing-claude-ship"}]},"349e4eb0-98c5-4d3d-8ae9-549f9eb0a7f1":{"publicId":"349e4eb0-98c5-4d3d-8ae9-549f9eb0a7f1","title":"Tidal将于12月9日起下架纯AI生成音乐","status":"active","sourceCount":5,"reportCount":5,"firstReportAt":"2026-11-24T15:06:26.000Z","latestAt":"2026-11-24T22:41:34.377Z","latest":"Tidal 宣布 12 月 9 日起下架纯 AI 生成音乐，年底预计删除超 2900 万首歌曲","digest":"音乐流媒体平台 Tidal 宣布，将从 12 月 9 日起封禁并下架完全由 AI 生成的曲目，成为首个全面封禁 AI 音乐的流媒体平台。Tidal 负责人 Robert Anderson 称，过去 90 天分发的曲目中 43% 被检测为 AI 生成，96% 的 AI 歌曲播放量为零。\n\n关于清理规模，各报道说法不一：TechCrunch 称到年底将删除超过 2900 万首，Ars Technica 则称将删除 2700 万首、占其曲库 6.3%。新规生效后，Tidal 预计每天拒绝约 8 万至 8.5 万首投稿，并使用 Ircam Amplify 检测工具和元数据核查来拦截纯 AI 投稿。\n\nTidal 表示仍接受 AI 辅助创作的作品，前提是 AI 不构成“唯一输出”、最终成品含人类创作元素。作为对比，Deezer 提供过滤开关，Spotify 和 YouTube Music 仅对 AI 内容打标签。","digestUpdatedAt":"2026-11-24T23:21:02.678Z","reports":[{"id":"fs4dkkx963wcoy8t0x9yczo72","title":"Tidal 宣布 12 月 9 日起下架纯 AI 生成音乐，年底预计删除超 2900 万首歌曲","summary":"音乐流媒体平台 Tidal 宣布将从 12 月 9 日起下架完全由 AI 生成的音乐，年底预计删除超 2900 万首歌曲，并禁止发行商分发纯 AI 曲目，新规实施后每天预计拒收 8-8.5 万首歌曲。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-24T22:41:34.377Z","url":"https://www.ithome.com/1/031/904.htm"},{"id":"m6nnt1i9fb8aw0mp646rukdvc","title":"Tidal 宣布 12 月 9 日起全面封禁纯 AI 生成音乐，将删除 2700 万首曲目","summary":"Tidal 宣布将全面封禁完全由 AI 生成的音乐，12 月 9 日删除平台上标注为 AI 的 2700 万首曲目，占其曲库总量 6.3%。数据显示过去 90 天其新增上传中 43% 为纯 AI 生成，11 月 6 日一度达 60%，而 96% 的 AI 标注曲目过去 90 天播放量为零。含人类创作元素、使用 AI 工具辅助的作品不受影响。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T17:34:34.000Z","url":"https://arstechnica.com/ai/2026/11/tidal-will-ban-fully-ai-generated-music-on-december-9/"},{"id":"fsuuia07co9foiuxxt7ff8fog","title":"Tidal 将于 12 月 9 日起封禁纯 AI 生成音乐，删除约 2900 万首曲目","summary":"流媒体平台 Tidal 宣布将于 12 月 9 日正式封禁纯 AI 生成音乐，届时删除约 2900 万首 AI 生成歌曲，并预计每天拒绝 8 万至 8.5 万条投稿。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T17:17:09.000Z","url":"https://www.theverge.com/entertainment/1041362/tidal-ai-music-ban"},{"id":"vmrrpjmr3lu3pcm99pr0uluc0","title":"Tidal 将封禁并下架超 2900 万首全 AI 生成歌曲","summary":"Tidal 宣布将从 12 月 9 日起封禁并删除完全由 AI 生成的歌曲，到年底将删除超过 2900 万首，并每天拒绝约 8 万至 8.5 万首投稿。过去 90 天该平台上传曲目中超过 43% 为 AI 生成，其中 96% 完全 AI 生成的歌曲没有任何播放量；Tidal 仍接受 AI 辅助创作的歌曲。Deezer 推出过滤开关，Spotify 和 YouTube Music 则选择仅打标签。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-24T16:46:00.000Z","url":"https://techcrunch.com/2026/11/24/tidal-to-ban-and-remove-millions-of-ai-generated-tracks-as-ai-slop-inundates-music-streaming/"},{"id":"a1uu4xcejqi0jxno12xmnm5d8","title":"Tidal 宣布全面下架纯 AI 生成音乐，成首个封禁 AI 音乐的流媒体平台","summary":"音乐流媒体 Tidal 宣布将从 12 月 9 日起移除全部完全由 AI 生成的曲目，成为首个全面封禁 AI 音乐的流媒体平台。Tidal 负责人 Robert Anderson 称过去 90 天内分发的曲目有 43% 被检测为 AI 生成，96% 的 AI 歌曲播放量为零，此次清理将移除 2900 万首曲目，此后每天拒绝 8 万至 8.5 万首歌。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-24T15:06:26.000Z","url":"https://variety.com/2026/music/news/tidal-bans-ai-generated-music-1236956924/"}]},"81de20a5-02a9-44a4-bc64-da0b8b916ab5":{"publicId":"81de20a5-02a9-44a4-bc64-da0b8b916ab5","title":"OpenAI公布GPT-6.2蛋白质设计湿实验验证结果","status":"active","sourceCount":5,"reportCount":10,"firstReportAt":"2026-11-24T13:00:00.000Z","latestAt":"2026-11-24T22:44:58.033Z","latest":"OpenAI 发布预印本论文称 GPT-6 可仅靠推理设计蛋白质并有实验验证","digest":"OpenAI发布预印本，称GPT-6系列模型仅凭推理和通用编程工具即可设计新蛋白的形状与序列，无需调用专用生物学模型，并公布GPT-6.2的湿实验验证结果。OpenAI称，与Onava合作测试的322个蛋白中35个显示结合证据，五个靶点均有结合物，Rohan Paul转述称结合率为10.9%；GPT-6.2为三种形状重新设计序列，107条新序列中14个蛋白显示结合；改造抗体靶点结合部位的两项实验中，182个改造小抗体里128个、272个抗体片段里179个保留结合能力。\n\nOpenAI同时指出局限：筛选候选时仍用到Boltz-2、ESMFold2等专用模型，因此还不能证明GPT能在没有这些模型帮助的情况下端到端设计蛋白；从序列预测完整蛋白结构也是短板，内部模型平均TM-score为0.38，ESMFold2为0.93。\n\nOpenAI将上述工作定位为概念验证，称下一步要测试这些蛋白质附着后能否发挥有用作用、攻克更难靶点并扩展到其他分子类型，目标是让科学家未来仅凭提示词设计可用药物。这些结合数据来自OpenAI自行公布的实验结果。","digestUpdatedAt":"2026-11-25T01:22:34.872Z","reports":[{"id":"a31pq2odhgiyopb0wo00mpp0i","title":"OpenAI 发布预印本论文称 GPT-6 可仅靠推理设计蛋白质并有实验验证","summary":"OpenAI 于 11 月 24 日发布预印本论文，称 GPT-6 系列无需专用生物模型，仅靠推理和通用编程工具即可设计蛋白质三维结构和氨基酸序列，并与合作机构 Onava 做了实验室验证。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-24T22:44:58.033Z","url":"https://www.ithome.com/1/031/902.htm"},{"id":"oximik7jrbczx2s6fzw0u0bjh","title":"Greg Brockman 转发 OpenAI 预印本：GPT-6 无需生物专用模型即可设计新蛋白","summary":"Greg Brockman 转发 OpenAI 引用的预印本，该报告展示了 GPT-6 系列模型蛋白质设计能力的湿实验验证。模型通过推理和代码设计新的蛋白质形状和序列，无需调用专门的生物学模型来生成。作者称这是推理和代码普遍解决问题能力的又一例证，链接 https://openai.com/index/gpt-6-models-demonstrate-intrinsic-protein-design-capabilities/。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-24T21:30:40.000Z","url":"https://x.com/gdb/status/2125341356503748716"},{"id":"vgfqeucxzz1b8hli8dq97nicd","title":"OpenAI 预印本展示 GPT-6 系列模型内生蛋白质设计能力，湿实验结合率 10.9%","summary":"OpenAI 发布新预印本，展示 GPT-6 系列模型仅凭推理和编写代码即可设计新蛋白形状与序列，无需调用专门生物模型。与 Onava 合作的湿实验中，基于 GPT-6.2 设计的蛋白在五个靶点上显示出结合证据，作者转述称结合率为 10.9%；内部研究模型在多项蛋白设计任务上持平或超越专门模型，重设计的抗体也保留结合能力。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-24T21:22:32.000Z","url":"https://x.com/rohanpaul_ai/status/2125339306185388060"},{"id":"hrupiq6rjdycgkc118krr5q92","title":"OpenAI 蛋白质设计概念验证","summary":"这是一个概念验证。接下来，我们想测试这些蛋白质在附着后是否能发挥有用作用，攻克更难的靶点，并将这项工作扩展到其他类型的分子。\n\n我们的目标是让科学家有朝一日只需通过提示词就能设计出可用的药物。我们希望加速蛋白质设计周期，并减少找到功能性蛋白质所需的实验次数。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:03:01.000Z","url":"https://x.com/OpenAI/status/2125334394491801883"},{"id":"esr0mb4n8pnafse6ly71gmfc3","title":"GPT-6.2 蛋白质序列设计与抗体改造湿实验结果公布","summary":"OpenAI 公布 GPT-6.2 蛋白质设计的补充实验结果：为其此前设计的三种形状重新设计序列，107 条新序列中 14 个蛋白在湿实验中显示结合。GPT-6.2 还改造了抗体的靶点结合部位，两项实验中 182 个改造小抗体里 128 个、272 个抗体片段里 179 个保留了结合能力。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:03:00.000Z","url":"https://x.com/OpenAI/status/2125334392814051724"},{"id":"vdpdwwuihdmb7ruz8ldh3yb69","title":"OpenAI 与研究伙伴 Onava 实验室验证 GPT-6.2 蛋白设计，322 个蛋白中 35 个显示结合证据","summary":"OpenAI 与研究伙伴 Onava 在实验室测试了蛋白设计的两个环节。GPT-6.2 负责设计蛋白形状，专业模型补全其余工作流程。在测试的 322 个蛋白中，35 个显示出结合证据，且五个靶点全部有 binder。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:03:00.000Z","url":"https://x.com/OpenAI/status/2125334391195070471"},{"id":"urocwl35zi2cki4c023xqwxdc","title":"OpenAI 测试 GPT-6.2 分子控制能力","summary":"我们从两个原子之间的单个键到蛋白质的整体形状，在多个尺度上测试了这种控制。\n\n对于 GPT-6.2，提示词可以识别小分子与蛋白质之间哪两个原子形成了键，然后询问分子的其余部分如何契合。其他提示词则指定了新蛋白质应在何处附着，以及应包含多少个螺旋或链。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:02:59.000Z","url":"https://x.com/OpenAI/status/2125334389387366627"},{"id":"md8lnz3g2gghd4dk7l1z1469j","title":"OpenAI内部研究模型蛋白质任务表现","summary":"性能随模型代际提升。\n\n在计算机测试中，一个内部研究模型在许多蛋白质任务上匹配或超越了专用模型，包括设计形状和预测分子如何结合。\n\n模型的书面推理和代码表明，它们借助数学、物理、化学和生物学知识来解决这些问题。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:02:58.000Z","url":"https://x.com/OpenAI/status/2125334385272774887"},{"id":"vld1kqsp7wkz3o3qo1ubc9sg9","title":"OpenAI 发布 preprint：湿实验验证 GPT-6 系列模型具备内在蛋白质设计能力","summary":"OpenAI 发布新 preprint，报告通过湿实验室验证 GPT-6 系列模型具备内在蛋白质设计能力。模型可依靠推理和代码设计新的蛋白质形状与序列，无需调用专用生物学模型来生成，详情见 openai.com/index/gpt-6-models-demonstrate-intrinsic-protein-design-capabilities/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-24T21:02:58.000Z","url":"https://x.com/OpenAI/status/2125334383490105601"},{"id":"yg04c9d5qnwzitqstg19c6ow2","title":"OpenAI 发布预印本：GPT-6 模型展现内在蛋白质设计能力","summary":"OpenAI 发布预印本，称 GPT-6 系列模型仅凭推理和通用编码工具即可设计新蛋白的结构与序列，无需调用专用生物学模型。与 Onava 的实验室测试中，基于 GPT-6.2 设计的 minibinder 在 5 个靶点上均出现结合证据，322 个 minibinder 中 35 个（10.9%）结合阳性；重设计的抗体片段 66% 保留结合。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-24T13:00:00.000Z","url":"https://openai.com/index/gpt-6-models-demonstrate-intrinsic-protein-design-capabilities/"}]}}};
